  "summary": "The code contained a critical XXE vulnerability and lacked robust error handling. I have secured the XML parser, added comprehensive error handling, and improved maintainability with docstrings and path constants.",
  "fixed_code": "from lxml import etree\n\n# Constants for XML structure\nPATH_NUMBER = \"number\"\nPATH_TOTAL = \"total\"\nPATH_LINES = \"lines/line\"\nPATH_SKU = \"sku\"\n\nclass InvoiceParsingError(Exception):\n    \"\"\"Custom exception for invoice parsing failures.\"\"\"\n    pass\n\ndef parse_invoice(xml_bytes: bytes):\n    \"\"\"Parses an invoice XML and returns a dictionary containing the invoice number, total, and a list of SKUs.\"\"\"\n    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False, dtd_validation=False)\n    try:\n        root = etree.fromstring(xml_bytes, parser)\n        return {\n            \"number\": root.findtext(PATH_NUMBER),\n            \"total\": root.findtext(PATH_TOTAL),\n            \"lines\": [li.findtext(PATH_SKU) for li in root.findall(PATH_LINES)],\n        }\n    except (etree.XMLSyntaxError, etree.DocumentInvalid) as e:\n        raise InvoiceParsingError(f\"Failed to parse invoice XML: {e}\")"
}
